const BASE='https://clerky-agent.creativehub254.chatgpt.site/api/zuno';
const SESSION='zuno-ai-preview-v1';let session=null;try{session=JSON.parse(sessionStorage.getItem(SESSION)||'null')}catch{}
export function aiReady(age){return !!session?.token&&session.ageBand===age&&session.expires>Date.now()}
export function disableAI(){session=null;try{sessionStorage.removeItem(SESSION)}catch{}}
async function request(path,body,signal,token){let r;try{r=await fetch(BASE+path,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:signal?AbortSignal.any([signal,AbortSignal.timeout(65000)]):AbortSignal.timeout(65000)})}catch(e){if(e.name==='AbortError')throw e;throw Object.assign(Error('The AI connection could not be reached.'),{code:'NETWORK_UNAVAILABLE'})}const d=await r.json();if(!r.ok)throw Object.assign(Error('The AI connection could not complete this request.'),{code:d.code||'UNAVAILABLE'});return d}
export async function enableAI(age){const d=await request('/session',{ageBand:age});session={token:d.token,ageBand:age,expires:Date.now()+d.expiresIn*1000};try{sessionStorage.setItem(SESSION,JSON.stringify(session))}catch{}return session}
export async function aiStatus(){try{const r=await fetch(BASE+'/status',{signal:AbortSignal.timeout(10000)});return await r.json()}catch{return {configured:false,mode:'unavailable'}}}
export async function askAI({question,ageBand,task='chat',signal}){if(!aiReady(ageBand))await enableAI(ageBand);try{return await request('/answer',{question,task},signal,session.token)}catch(e){if(e.code!=='PREVIEW_SESSION_REQUIRED')throw e;await enableAI(ageBand);return request('/answer',{question,task},signal,session.token)}}
export function aiError(code){return ({DAILY_LIMIT:'Today’s shared AI allowance is used up. The library and games still work.',SESSION_LIMIT:'This preview has reached its 40-question daily limit. Keep exploring the library or games.',FREE_QUOTA_LIMIT:'The free AI allowance is taking a break. Try again later or open a library discovery.',PREVIEW_SESSION_REQUIRED:'Reconnect Zuno AI for this reading band.',NO_FREE_PROVIDER:'No eligible free AI route is currently available.',ANSWER_CHECKS_UNAVAILABLE:'The answer checks could not finish. Try a different question or use the library.'})[code]||'The AI connection could not finish this answer. Try again later or use a library discovery.'}
